import{_ as s}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as a,b as e,o as p}from"./app-BOuFtv26.js";const l={};function c(t,n){return p(),a("div",null,n[0]||(n[0]=[e(`<h2 id="引入-从-makefile-到更现代的构建" tabindex="-1"><a class="header-anchor" href="#引入-从-makefile-到更现代的构建"><span>引入：从 Makefile 到更现代的构建</span></a></h2><p>上一篇的 <code>Makefile</code> 虽然能自动构建项目，但有几个明显的不足：</p><ul><li><span style="color:#409EFF;">跨平台困难</span>：Windows 用 <code>MinGW</code> 或 <code>MSVC</code>，Linux 用 <code>GCC</code>，macOS 用 <code>Clang</code>，<code>Makefile</code> 要为每个平台写不同版本。</li><li><span style="color:#409EFF;">依赖管理原始</span>：如果项目依赖了第三方库（如 <code>SDL2</code>、<code>OpenGL</code>），找库、配置路径全靠手动。</li><li><span style="color:#409EFF;">语法简陋</span>：条件判断、循环、函数等高级功能写起来很别扭。</li></ul><p>于是社区发展出了更高级的构建工具。最流行的是 <span style="color:#409EFF;">CMake</span>（事实标准），新兴的还有 <span style="color:#409EFF;">XMake</span>（更简洁的语法）。它们不直接编译代码，而是先生成本地构建文件（如 <code>Makefile</code>、<code>Visual Studio 解决方案</code>），再调用底层的编译器。</p><hr><h2 id="学习目标" tabindex="-1"><a class="header-anchor" href="#学习目标"><span>学习目标</span></a></h2><ul><li>理解 CMake 和 XMake 的基本概念</li><li>学会编写 <code>CMakeLists.txt</code> 和 <code>xmake.lua</code></li><li>理解静态链接库（<code>.a</code>/<code>.lib</code>）与动态链接库（<code>.so</code>/<code>.dll</code>/<code>.dylib</code>）的区别</li><li>学会在项目中引入和链接第三方库（以 SDL2 为例）</li><li>了解交叉编译的概念</li></ul><hr><h2 id="静态链接库与动态链接库" tabindex="-1"><a class="header-anchor" href="#静态链接库与动态链接库"><span>静态链接库与动态链接库</span></a></h2><p><span style="color:#E6A23C;">在动手写代码之前，先弄清楚两种库的区别，因为后面你会频繁遇到。</span></p><h3 id="静态链接库" tabindex="-1"><a class="header-anchor" href="#静态链接库"><span>静态链接库</span></a></h3><ul><li><span style="color:#409EFF;">Windows</span>：<code>.lib</code></li><li><span style="color:#409EFF;">Linux</span>：<code>.a</code></li><li><span style="color:#409EFF;">macOS</span>：<code>.a</code></li></ul><p>静态库在<span style="color:#409EFF;">链接阶段</span>被完整地复制到可执行文件中。生成的可执行文件<span style="color:#409EFF;">不依赖外部的库文件</span>，可以直接运行。</p><p>优点：部署简单，只要一个可执行文件就能跑。<br> 缺点：多个程序使用同一个静态库时，每个程序都有一份副本，浪费磁盘和内存；库升级时需要重新链接。</p><h3 id="动态链接库" tabindex="-1"><a class="header-anchor" href="#动态链接库"><span>动态链接库</span></a></h3><ul><li><span style="color:#409EFF;">Windows</span>：<code>.dll</code>（搭配 <code>.lib</code> 导入库）</li><li><span style="color:#409EFF;">Linux</span>：<code>.so</code></li><li><span style="color:#409EFF;">macOS</span>：<code>.dylib</code></li></ul><p>动态库在<span style="color:#409EFF;">运行阶段</span>才被加载到内存中。可执行文件只记录&quot;我需要这个库&quot;，运行时由系统加载器去找并加载。</p><p>优点：多个程序共享一份库文件，节省内存；库升级时只要替换 <code>.dll</code>/<code>.so</code> 文件即可，程序无需重新链接。<br> 缺点：部署时需要带上所有依赖的 <code>.dll</code>/<code>.so</code>，缺少任何一个程序都无法启动。</p><h3 id="怎么选" tabindex="-1"><a class="header-anchor" href="#怎么选"><span>怎么选？</span></a></h3><ul><li>小工具、教学项目：静态链接最简单，一个文件到处跑</li><li>大型项目、需要频繁更新库：动态链接更灵活</li><li>第三方库通常两种都提供，看你需要</li></ul><hr><h2 id="使用-sdl2-开发一个简单游戏" tabindex="-1"><a class="header-anchor" href="#使用-sdl2-开发一个简单游戏"><span>使用 SDL2 开发一个简单游戏</span></a></h2><p><code>SDL2</code>（Simple DirectMedia Layer）是一个跨平台的多媒体库，提供窗口创建、图像渲染、音频播放、键盘鼠标输入等功能。我们用它来做一个简单的弹球游戏，同时学习如何管理外部依赖。</p><h3 id="sdl2-的安装" tabindex="-1"><a class="header-anchor" href="#sdl2-的安装"><span>SDL2 的安装</span></a></h3><p>首先需要把 <code>SDL2</code> 安装到系统上。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Windows (MSYS2)</span></span>
<span class="line">pacman <span class="token parameter variable">-S</span> mingw-w64-ucrt-x86_64-SDL2 mingw-w64-ucrt-x86_64-SDL2_mixer mingw-w64-ucrt-x86_64-SDL2_image mingw-w64-ucrt-x86_64-SDL2_ttf</span>
<span class="line"></span>
<span class="line"><span class="token comment"># macOS (Homebrew)</span></span>
<span class="line">brew <span class="token function">install</span> sdl2 sdl2_mixer sdl2_image sdl2_ttf</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Linux (Ubuntu/Debian)</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">apt</span> <span class="token function">install</span> libsdl2-dev libsdl2-mixer-dev libsdl2-image-dev libsdl2-ttf-dev</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="一个简单的-sdl2-弹球游戏" tabindex="-1"><a class="header-anchor" href="#一个简单的-sdl2-弹球游戏"><span>一个简单的 SDL2 弹球游戏</span></a></h3><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c"><pre><code class="language-c"><span class="line"><span class="token comment">// game.c</span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;SDL2/SDL.h&gt;</span></span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdio.h&gt;</span></span></span>
<span class="line"></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name">WINDOW_WIDTH</span> <span class="token expression"><span class="token number">800</span></span></span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name">WINDOW_HEIGHT</span> <span class="token expression"><span class="token number">600</span></span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token keyword">int</span> argc<span class="token punctuation">,</span> <span class="token keyword">char</span><span class="token operator">*</span> argv<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 初始化 SDL</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">SDL_Init</span><span class="token punctuation">(</span>SDL_INIT_VIDEO<span class="token punctuation">)</span> <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;SDL 初始化失败: %s\\n&quot;</span><span class="token punctuation">,</span> <span class="token function">SDL_GetError</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 创建窗口</span></span>
<span class="line">    SDL_Window<span class="token operator">*</span> window <span class="token operator">=</span> <span class="token function">SDL_CreateWindow</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token string">&quot;弹球游戏&quot;</span><span class="token punctuation">,</span> SDL_WINDOWPOS_CENTERED<span class="token punctuation">,</span> SDL_WINDOWPOS_CENTERED<span class="token punctuation">,</span></span>
<span class="line">        WINDOW_WIDTH<span class="token punctuation">,</span> WINDOW_HEIGHT<span class="token punctuation">,</span> SDL_WINDOW_SHOWN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>window<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;窗口创建失败: %s\\n&quot;</span><span class="token punctuation">,</span> <span class="token function">SDL_GetError</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">SDL_Quit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 创建渲染器</span></span>
<span class="line">    SDL_Renderer<span class="token operator">*</span> renderer <span class="token operator">=</span> <span class="token function">SDL_CreateRenderer</span><span class="token punctuation">(</span></span>
<span class="line">        window<span class="token punctuation">,</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span> SDL_RENDERER_ACCELERATED<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>renderer<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;渲染器创建失败: %s\\n&quot;</span><span class="token punctuation">,</span> <span class="token function">SDL_GetError</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">SDL_DestroyWindow</span><span class="token punctuation">(</span>window<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">SDL_Quit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 球的属性</span></span>
<span class="line">    <span class="token keyword">float</span> ball_x <span class="token operator">=</span> <span class="token number">400</span><span class="token punctuation">,</span> ball_y <span class="token operator">=</span> <span class="token number">300</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">float</span> ball_vx <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span> ball_vy <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">int</span> ball_radius <span class="token operator">=</span> <span class="token number">15</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">int</span> running <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    SDL_Event event<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 游戏主循环</span></span>
<span class="line">    <span class="token keyword">while</span> <span class="token punctuation">(</span>running<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 处理事件</span></span>
<span class="line">        <span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token function">SDL_PollEvent</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>event<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>event<span class="token punctuation">.</span>type <span class="token operator">==</span> SDL_QUIT<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                running <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 更新球的位置</span></span>
<span class="line">        ball_x <span class="token operator">+=</span> ball_vx<span class="token punctuation">;</span></span>
<span class="line">        ball_y <span class="token operator">+=</span> ball_vy<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 边界碰撞检测</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>ball_x <span class="token operator">-</span> ball_radius <span class="token operator">&lt;</span> <span class="token number">0</span> <span class="token operator">||</span> ball_x <span class="token operator">+</span> ball_radius <span class="token operator">&gt;</span> WINDOW_WIDTH<span class="token punctuation">)</span></span>
<span class="line">            ball_vx <span class="token operator">=</span> <span class="token operator">-</span>ball_vx<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>ball_y <span class="token operator">-</span> ball_radius <span class="token operator">&lt;</span> <span class="token number">0</span> <span class="token operator">||</span> ball_y <span class="token operator">+</span> ball_radius <span class="token operator">&gt;</span> WINDOW_HEIGHT<span class="token punctuation">)</span></span>
<span class="line">            ball_vy <span class="token operator">=</span> <span class="token operator">-</span>ball_vy<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 渲染</span></span>
<span class="line">        <span class="token function">SDL_SetRenderDrawColor</span><span class="token punctuation">(</span>renderer<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 黑色背景</span></span>
<span class="line">        <span class="token function">SDL_RenderClear</span><span class="token punctuation">(</span>renderer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 画球（白色圆形，用矩形近似）</span></span>
<span class="line">        SDL_Rect ball <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token punctuation">(</span><span class="token keyword">int</span><span class="token punctuation">)</span><span class="token punctuation">(</span>ball_x <span class="token operator">-</span> ball_radius<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">(</span><span class="token keyword">int</span><span class="token punctuation">)</span><span class="token punctuation">(</span>ball_y <span class="token operator">-</span> ball_radius<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            ball_radius <span class="token operator">*</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">            ball_radius <span class="token operator">*</span> <span class="token number">2</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">SDL_SetRenderDrawColor</span><span class="token punctuation">(</span>renderer<span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 白色</span></span>
<span class="line">        <span class="token function">SDL_RenderFillRect</span><span class="token punctuation">(</span>renderer<span class="token punctuation">,</span> <span class="token operator">&amp;</span>ball<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token function">SDL_RenderPresent</span><span class="token punctuation">(</span>renderer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">SDL_Delay</span><span class="token punctuation">(</span><span class="token number">16</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 约 60 FPS</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 清理</span></span>
<span class="line">    <span class="token function">SDL_DestroyRenderer</span><span class="token punctuation">(</span>renderer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">SDL_DestroyWindow</span><span class="token punctuation">(</span>window<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">SDL_Quit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个程序创建了一个窗口，里面有一个白色方块在弹跳。虽然简单，但它包含了游戏程序的基本骨架：初始化、事件循环、更新状态、渲染、清理。</p><hr><h2 id="用-cmake-构建-sdl2-项目" tabindex="-1"><a class="header-anchor" href="#用-cmake-构建-sdl2-项目"><span>用 CMake 构建 SDL2 项目</span></a></h2><h3 id="什么是-cmake" tabindex="-1"><a class="header-anchor" href="#什么是-cmake"><span>什么是 CMake</span></a></h3><p><code>CMake</code> 是目前 <code>C/C++</code> 项目最流行的构建系统生成器。它不直接编译，而是读取 <code>CMakeLists.txt</code> 配置文件，生成对应平台的构建文件（<code>Makefile</code>、<code>Visual Studio 解决方案</code>、<code>Ninja</code> 构建文件等）。</p><h3 id="cmakelists-txt-的基本写法" tabindex="-1"><a class="header-anchor" href="#cmakelists-txt-的基本写法"><span>CMakeLists.txt 的基本写法</span></a></h3><p>在项目根目录下创建 <code>CMakeLists.txt</code>：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token comment"># 指定最低 CMake 版本</span></span>
<span class="line"><span class="token keyword">cmake_minimum_required</span><span class="token punctuation">(</span><span class="token property">VERSION</span> <span class="token number">3.10</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 项目名称和语言</span></span>
<span class="line"><span class="token keyword">project</span><span class="token punctuation">(</span>BouncingBall C<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 指定 C 语言标准</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_C_STANDARD</span> <span class="token number">11</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_C_STANDARD_REQUIRED</span> <span class="token boolean">ON</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查找 SDL2 库</span></span>
<span class="line"><span class="token keyword">find_package</span><span class="token punctuation">(</span>SDL2 REQUIRED<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 添加可执行文件目标</span></span>
<span class="line"><span class="token keyword">add_executable</span><span class="token punctuation">(</span>bouncing_ball game.c<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 链接 SDL2 库</span></span>
<span class="line"><span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>bouncing_ball <span class="token namespace">PRIVATE</span> <span class="token inserted class-name">SDL2::SDL2</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逐行解释：</p><ul><li><code>cmake_minimum_required(VERSION 3.10)</code>：声明用的 CMake 版本。版本太旧可能不支持某些语法。</li><li><code>project(BouncingBall C)</code>：项目名和语言。CMake 会根据语言选择合适的编译器。</li><li><code>set(CMAKE_C_STANDARD 11)</code>：要求使用 <code>C11</code> 标准。</li><li><code>find_package(SDL2 REQUIRED)</code>：<span style="color:#409EFF;">查找 SDL2 库</span>。<code>REQUIRED</code> 表示如果找不到就报错。CMake 会在系统的标准路径（以及你额外指定的路径）下搜索 <code>SDL2</code> 的配置脚本（<code>SDL2Config.cmake</code> 或 <code>sdl2-config.cmake</code>）。</li><li><code>add_executable(bouncing_ball game.c)</code>：声明要生成的可执行文件及其源文件。</li><li><code>target_link_libraries(bouncing_ball PRIVATE SDL2::SDL2)</code>：把 SDL2 库链接到目标。<code>PRIVATE</code> 表示这个依赖只对 <code>bouncing_ball</code> 自己可见。</li></ul><h3 id="构建和运行" tabindex="-1"><a class="header-anchor" href="#构建和运行"><span>构建和运行</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 创建构建目录（CMake 推荐在单独的目录中构建，不污染源码目录）</span></span>
<span class="line"><span class="token function">mkdir</span> build <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> build</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成构建文件（默认生成 Makefile）</span></span>
<span class="line">cmake <span class="token punctuation">..</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 编译</span></span>
<span class="line"><span class="token function">make</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 运行</span></span>
<span class="line">./bouncing_ball</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用 <code>cmake ..</code> 时，CMake 会读取上一级目录的 <code>CMakeLists.txt</code>，自动检测编译器、查找依赖库，然后生成 <code>Makefile</code>。之后 <code>make</code> 编译，和上篇一样。</p><h3 id="cmake-中链接第三方库的通用方式" tabindex="-1"><a class="header-anchor" href="#cmake-中链接第三方库的通用方式"><span>CMake 中链接第三方库的通用方式</span></a></h3><p><code>target_link_libraries</code> 是 CMake 中链接库的核心命令。通用的形式是：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>目标名称 可见性 库<span class="token number">1</span> 库<span class="token number">2</span> ...<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>可见性有三种：</p><table><thead><tr><th>可见性</th><th>含义</th></tr></thead><tbody><tr><td><code>PRIVATE</code></td><td>只供当前目标使用，不传递给依赖当前目标的其他目标</td></tr><tr><td><code>PUBLIC</code></td><td>既供当前目标使用，也传递给依赖者</td></tr><tr><td><code>INTERFACE</code></td><td>当前目标不使用，只传递给依赖者（常用于纯头文件库）</td></tr></tbody></table><p>对于 <code>find_package</code> 找到的库，通常用 <code>PRIVATE</code> 链接即可。</p><h3 id="如果-find-package-找不到-sdl2" tabindex="-1"><a class="header-anchor" href="#如果-find-package-找不到-sdl2"><span>如果 find_package 找不到 SDL2</span></a></h3><p><code>find_package</code> 在系统标准路径下搜索。如果 SDL2 安装在非标准位置（如通过 <code>MSYS2</code> 安装到 <code>C:\\msys64</code>），需要手动指定路径：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token comment"># 方法一：在运行 cmake 时指定</span></span>
<span class="line">cmake .. -DCMAKE_PREFIX_PATH=C:/msys64/ucrt64</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 方法二：在 CMakeLists.txt 中指定（不推荐，硬编码路径不好移植）</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_PREFIX_PATH</span> <span class="token string">&quot;C:/msys64/ucrt64&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>CMAKE_PREFIX_PATH</code> 告诉 CMake 去哪些额外目录搜索库的配置文件。</p><p>你也可以从网上（如 <code>https://github.com/libsdl-org/SDL/releases</code>）下载 SDL2 的预编译开发包，解压后同样用 <code>CMAKE_PREFIX_PATH</code> 指向解压目录。</p><hr><h2 id="用-xmake-构建-sdl2-项目" tabindex="-1"><a class="header-anchor" href="#用-xmake-构建-sdl2-项目"><span>用 XMake 构建 SDL2 项目</span></a></h2><p><code>XMake</code> 是一个比 CMake 更现代化的构建工具，语法更简洁（基于 Lua），而且内置了包管理——不需要提前安装 SDL2，XMake 会自动从网上下载。</p><h3 id="安装-xmake" tabindex="-1"><a class="header-anchor" href="#安装-xmake"><span>安装 XMake</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Windows (scoop)</span></span>
<span class="line">scoop <span class="token function">install</span> xmake</span>
<span class="line"></span>
<span class="line"><span class="token comment"># macOS (Homebrew)</span></span>
<span class="line">brew <span class="token function">install</span> xmake</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Linux</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-f</span> https://xmake.io/shget.text <span class="token operator">|</span> <span class="token function">sh</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="xmake-lua-的写法" tabindex="-1"><a class="header-anchor" href="#xmake-lua-的写法"><span>xmake.lua 的写法</span></a></h3><p>在项目根目录下创建 <code>xmake.lua</code>：</p><div class="language-lua line-numbers-mode" data-highlighter="prismjs" data-ext="lua"><pre><code class="language-lua"><span class="line"><span class="token comment">-- 项目名称和语言</span></span>
<span class="line"><span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;bouncing_ball&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;game.c&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">add_requires</span><span class="token punctuation">(</span><span class="token string">&quot;sdl2&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">add_packages</span><span class="token punctuation">(</span><span class="token string">&quot;sdl2&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逐行解释：</p><ul><li><code>target(&quot;bouncing_ball&quot;)</code>：定义一个构建目标。</li><li><code>set_kind(&quot;binary&quot;)</code>：目标是可执行文件（还有 <code>static</code> 静态库、<code>shared</code> 动态库）。</li><li><code>add_files(&quot;game.c&quot;)</code>：添加源文件。</li><li><code>add_requires(&quot;sdl2&quot;)</code>：声明需要 SDL2 库。XMake 会自动从网上下载并编译 SDL2。</li><li><code>add_packages(&quot;sdl2&quot;)</code>：把 SDL2 链接到目标。</li></ul><h3 id="构建和运行-1" tabindex="-1"><a class="header-anchor" href="#构建和运行-1"><span>构建和运行</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 配置、下载依赖、编译一步完成</span></span>
<span class="line">xmake</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 运行</span></span>
<span class="line">xmake run</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>XMake 的语法比 CMake 直观很多，而且内置包管理意味着你不再需要手动安装 SDL2。这也是它越来越受欢迎的原因。</p><h3 id="xmake-的更多配置" tabindex="-1"><a class="header-anchor" href="#xmake-的更多配置"><span>XMake 的更多配置</span></a></h3><div class="language-lua line-numbers-mode" data-highlighter="prismjs" data-ext="lua"><pre><code class="language-lua"><span class="line"><span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;my_app&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/*.c&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">add_includedirs</span><span class="token punctuation">(</span><span class="token string">&quot;include&quot;</span><span class="token punctuation">)</span>       <span class="token comment">-- 添加头文件搜索路径</span></span>
<span class="line">    <span class="token function">set_languages</span><span class="token punctuation">(</span><span class="token string">&quot;c11&quot;</span><span class="token punctuation">)</span>             <span class="token comment">-- 设置 C 语言标准</span></span>
<span class="line">    <span class="token function">add_requires</span><span class="token punctuation">(</span><span class="token string">&quot;sdl2&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;sdl2_mixer&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;sdl2_image&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token function">add_packages</span><span class="token punctuation">(</span><span class="token string">&quot;sdl2&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;sdl2_mixer&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;sdl2_image&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">-- 编译选项</span></span>
<span class="line"><span class="token function">set_config</span><span class="token punctuation">(</span><span class="token string">&quot;cflags&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;-Wall -g&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="工具链选择与交叉编译" tabindex="-1"><a class="header-anchor" href="#工具链选择与交叉编译"><span>工具链选择与交叉编译</span></a></h2><h3 id="工具链是什么" tabindex="-1"><a class="header-anchor" href="#工具链是什么"><span>工具链是什么</span></a></h3><p><span style="color:#409EFF;">工具链</span>（Toolchain）是一组工具的集合，包括编译器、链接器、汇编器、调试器等。不同的平台有不同的工具链：</p><table><thead><tr><th>平台</th><th>常用工具链</th></tr></thead><tbody><tr><td>Windows (x86)</td><td><code>MinGW-w64</code>（GCC）、<code>MSVC</code>（cl.exe）</td></tr><tr><td>Linux (x86)</td><td><code>GCC</code>、<code>Clang</code></td></tr><tr><td>macOS (x86/ARM)</td><td><code>Apple Clang</code>（Xcode Command Line Tools）</td></tr><tr><td>ARM 嵌入式</td><td><code>arm-none-eabi-gcc</code></td></tr></tbody></table><h3 id="在-cmake-中选择工具链" tabindex="-1"><a class="header-anchor" href="#在-cmake-中选择工具链"><span>在 CMake 中选择工具链</span></a></h3><p>CMake 会自动检测当前系统的默认工具链。如果要指定特定的工具链，可以在运行 <code>cmake</code> 时设置：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用 MinGW（在 Windows 上）</span></span>
<span class="line">cmake <span class="token punctuation">..</span> <span class="token parameter variable">-G</span> <span class="token string">&quot;MinGW Makefiles&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 MSVC（在 Windows 上，需要从 Developer Command Prompt 运行）</span></span>
<span class="line">cmake <span class="token punctuation">..</span> <span class="token parameter variable">-G</span> <span class="token string">&quot;Visual Studio 17 2022&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 Ninja（更快的构建系统）</span></span>
<span class="line">cmake <span class="token punctuation">..</span> <span class="token parameter variable">-G</span> <span class="token string">&quot;Ninja&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="交叉编译" tabindex="-1"><a class="header-anchor" href="#交叉编译"><span>交叉编译</span></a></h3><p><span style="color:#409EFF;">交叉编译</span>（Cross Compilation）是在一个平台上编译出另一个平台可运行的程序。比如在 Windows 上编译 Linux 可执行文件，或者在 x86 电脑上编译 ARM 开发板的程序。</p><p>CMake 通过<span style="color:#409EFF;">工具链文件</span>（toolchain file）来支持交叉编译。创建一个 <code>arm-toolchain.cmake</code>：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token comment"># 指定目标系统</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_SYSTEM_NAME</span> Linux<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_SYSTEM_PROCESSOR</span> arm<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 指定交叉编译器</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_C_COMPILER</span> arm-linux-gnueabihf-gcc<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_CXX_COMPILER</span> arm-linux-gnueabihf-g++<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 指定目标系统的根文件系统路径（用于查找库和头文件）</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_SYSROOT</span> /path/to/arm/sysroot<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后这样构建：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">cmake <span class="token punctuation">..</span> <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>arm-toolchain.cmake</span>
<span class="line"><span class="token function">make</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>在 XMake 中配置交叉编译更简洁：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 列出可用的工具链</span></span>
<span class="line">xmake show <span class="token parameter variable">-l</span> toolchains</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 指定工具链</span></span>
<span class="line">xmake f <span class="token parameter variable">--toolchain</span><span class="token operator">=</span>arm-linux-gnueabihf</span>
<span class="line">xmake</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">为什么要交叉编译？</p><p>嵌入式设备（如树莓派、STM32）的运算能力和内存有限，无法直接在上面编译大型程序。交叉编译让你用强大的 PC 编译，再把编译好的程序传过去运行。</p><p>对于初学者来说，理解交叉编译的概念就足够了。真正用到时再深入学习。</p></div><hr><h2 id="cmake-中的动态链接与静态链接" tabindex="-1"><a class="header-anchor" href="#cmake-中的动态链接与静态链接"><span>CMake 中的动态链接与静态链接</span></a></h2><p>CMake 默认使用动态链接（生成的可执行文件依赖 <code>.so</code>/<code>.dll</code>）。如果要强制静态链接，可以：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token comment"># 方式一：要求静态链接所有库</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_FIND_LIBRARY_SUFFIXES</span> .a <span class="token punctuation">\${</span><span class="token variable">CMAKE_FIND_LIBRARY_SUFFIXES</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 方式二：如果库同时提供了静态和动态版本，显式指定</span></span>
<span class="line"><span class="token keyword">find_package</span><span class="token punctuation">(</span>SDL2 REQUIRED<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>bouncing_ball <span class="token namespace">PRIVATE</span> <span class="token inserted class-name">SDL2::SDL2</span>-static<span class="token punctuation">)</span>  <span class="token comment"># 静态版本</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>判断一个库提供的是动态还是静态版本，要看 <code>find_package</code> 找到的 target 名字。通常 <code>SDL2::SDL2</code> 是动态，<code>SDL2::SDL2-static</code> 是静态，但不同的库命名规则不同，需要查阅对应库的文档。</p><p>在 XMake 中：</p><div class="language-lua line-numbers-mode" data-highlighter="prismjs" data-ext="lua"><pre><code class="language-lua"><span class="line"><span class="token function">add_requires</span><span class="token punctuation">(</span><span class="token string">&quot;sdl2&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>configs <span class="token operator">=</span> <span class="token punctuation">{</span>shared <span class="token operator">=</span> <span class="token keyword">false</span><span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span>  <span class="token comment">-- 静态链接</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="如何查找第三方库的-cmake-配置" tabindex="-1"><a class="header-anchor" href="#如何查找第三方库的-cmake-配置"><span>如何查找第三方库的 CMake 配置</span></a></h2><p>当你需要引入一个新的第三方库时，如何知道 <code>find_package</code> 怎么写？</p><ol><li><span style="color:#409EFF;">查看库的官方文档</span>：大多数现代库都会提供 CMake 集成指南。</li><li><span style="color:#409EFF;">查看库的安装目录</span>：安装后，在库的 <code>lib/cmake</code> 目录下找 <code>.cmake</code> 文件。</li><li><span style="color:#409EFF;">搜索 GitHub</span>：搜索 <code>库名 cmake find_package</code>。</li><li><span style="color:#409EFF;">使用 CMake 的 <code>find_package</code> 手册</span>：</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">cmake --help-module-list <span class="token operator">|</span> <span class="token function">grep</span> SDL</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="5"><li><span style="color:#409EFF;">对于没有提供 CMake 配置的旧库</span>，可以用 <code>FindXXX.cmake</code> 模块或手动指定路径：</li></ol><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token comment"># 手动指定库路径（不推荐，除非万不得已）</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span>SDL2_INCLUDE_DIR <span class="token string">&quot;C:/path/to/SDL2/include&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span>SDL2_LIBRARY <span class="token string">&quot;C:/path/to/SDL2/lib/libSDL2.a&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">find_package</span><span class="token punctuation">(</span>SDL2 REQUIRED<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="常见错误与注意事项" tabindex="-1"><a class="header-anchor" href="#常见错误与注意事项"><span>常见错误与注意事项</span></a></h2><ol><li><span style="color:#F56C6C;"><code>find_package</code> 找不到库</span>：库没安装，或安装在非标准路径。用 <code>CMAKE_PREFIX_PATH</code> 指定搜索路径。</li><li><span style="color:#F56C6C;">链接时提示 <code>undefined reference</code></span>：忘记链接某个库，或者链接顺序不对。在 CMake 中确保所有 <code>target_link_libraries</code> 写全了。</li><li><span style="color:#F56C6C;">运行时提示找不到 <code>.dll</code>/<code>.so</code></span>：动态库不在系统的库搜索路径中。Windows 上可以把 <code>.dll</code> 和可执行文件放在同一目录，Linux 上可以设置 <code>LD_LIBRARY_PATH</code>。</li><li><span style="color:#F56C6C;">CMake 版本太低</span>：某些语法需要新版本支持。升级 CMake 或在配置中降低要求。</li><li><span style="color:#F56C6C;">XMake 下载依赖失败</span>：网络问题导致无法下载。检查网络，或配置镜像源。</li></ol><hr><h2 id="现代-cmake-以-target-为中心" tabindex="-1"><a class="header-anchor" href="#现代-cmake-以-target-为中心"><span>现代 CMake 以 target 为中心</span></a></h2><p>不要把所有设置都放进全局变量。先创建目标，再把需求绑定给目标：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token keyword">cmake_minimum_required</span><span class="token punctuation">(</span><span class="token property">VERSION</span> <span class="token number">3.20</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">project</span><span class="token punctuation">(</span>tiny_game LANGUAGES C<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">add_executable</span><span class="token punctuation">(</span>tiny_game game.c<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">target_compile_features</span><span class="token punctuation">(</span>tiny_game <span class="token namespace">PRIVATE</span> c_std_17<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">target_compile_options</span><span class="token punctuation">(</span>tiny_game <span class="token namespace">PRIVATE</span></span>
<span class="line">    <span class="token punctuation">$&lt;</span><span class="token punctuation">$&lt;</span>C_COMPILER_ID:GNU,Clang<span class="token punctuation">&gt;</span>:-Wall;-Wextra;-Wpedantic<span class="token punctuation">&gt;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>PRIVATE</code> 表示这些要求只用于当前目标；库项目还会用 <code>PUBLIC</code> 和 <code>INTERFACE</code> 传播头文件目录、编译特性和链接依赖。</p><h2 id="优先链接导入目标" tabindex="-1"><a class="header-anchor" href="#优先链接导入目标"><span>优先链接导入目标</span></a></h2><p>第三方包若提供 CMake 配置，常暴露类似 <code>SDL2::SDL2</code> 的导入目标：</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token keyword">find_package</span><span class="token punctuation">(</span>SDL2 CONFIG REQUIRED<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>tiny_game <span class="token namespace">PRIVATE</span> <span class="token inserted class-name">SDL2::SDL2</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>导入目标会携带正确头文件目录、库路径和平台依赖，比手写绝对路径更可移植。不同 SDL2 安装方式提供的包名和目标可能不同，应查看该包实际导出的 CMake 配置。</p><h2 id="始终使用源外构建" tabindex="-1"><a class="header-anchor" href="#始终使用源外构建"><span>始终使用源外构建</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">cmake <span class="token parameter variable">-S</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Debug</span>
<span class="line">cmake <span class="token parameter variable">--build</span> build</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>-S</code> 指源目录，<code>-B</code> 指构建目录。删除 <code>build</code> 就能清理生成文件，不污染源码。</p><p>多配置生成器（如 Visual Studio）通常在构建时指定配置：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">--config</span> Debug</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="静态和动态链接不是一个全局开关" tabindex="-1"><a class="header-anchor" href="#静态和动态链接不是一个全局开关"><span>静态和动态链接不是一个全局开关</span></a></h2><p>库是否可静态链接、依赖是否也有静态版本、许可证和运行时选择都要逐目标确认。强行设置全局后缀或硬编码 <code>.a</code> / <code>.lib</code> 容易破坏跨平台构建。优先使用包提供的目标和选项。</p><h2 id="构建系统不能替代依赖管理" tabindex="-1"><a class="header-anchor" href="#构建系统不能替代依赖管理"><span>构建系统不能替代依赖管理</span></a></h2><p>CMake 描述怎样构建和连接目标，但库从哪里安装、版本怎样固定，还可能由系统包管理器、vcpkg、Conan、FetchContent 或 XMake 包管理处理。教程示例要把“发现依赖失败”和“源码编译失败”分开排查。</p><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结"><span>小结</span></a></h2><ul><li>静态库（<code>.a</code>/<code>.lib</code>）在链接时嵌入可执行文件，动态库（<code>.so</code>/<code>.dll</code>/<code>.dylib</code>）在运行时加载</li><li>CMake 通过 <code>CMakeLists.txt</code> 描述项目结构，用 <code>find_package</code> 查找依赖，<code>target_link_libraries</code> 链接库</li><li>XMake 用 Lua 语法，内置包管理，使用更简洁</li><li>交叉编译是在一个平台上编译另一个平台的可执行程序</li><li>引入第三方库时，优先查看官方文档，次选 <code>CMAKE_PREFIX_PATH</code></li></ul><p>到这里，你已经有能力搭建完整的 <code>C/C++</code> 开发环境、使用调试器定位 bug、用 Makefile 或 CMake/XMake 管理项目了。这些工具和经验会在后续的学习和实际开发中持续发挥作用。</p>`,122)]))}const d=s(l,[["render",c]]),r=JSON.parse(`{"path":"/posts/C-Cpp-%E8%AF%AD%E8%A8%80%E4%B8%8E%E7%A8%8B%E5%BA%8F%E8%AE%BE%E8%AE%A1/71-cmake-sdl2.html","title":"CMake 与 XMake：现代项目构建","lang":"zh-CN","frontmatter":{"title":"CMake 与 XMake：现代项目构建","date":"2026-07-20T00:00:00.000Z","icon":"hammer","order":71,"category":["C/C++ 语言与程序设计"],"tag":["CMake","XMake","SDL2","构建工具","交叉编译","链接库"],"author":"Kingcq","description":"引入：从 Makefile 到更现代的构建 上一篇的 Makefile 虽然能自动构建项目，但有几个明显的不足： 跨平台困难：Windows 用 MinGW 或 MSVC，Linux 用 GCC，macOS 用 Clang，Makefile 要为每个平台写不同版本。 依赖管理原始：如果项目依赖了第三方库（如 SDL2、OpenGL），找库、配置路径全靠...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"CMake 与 XMake：现代项目构建\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-07-20T00:00:00.000Z\\",\\"dateModified\\":\\"2026-07-26T18:00:30.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Kingcq\\"}]}"],["meta",{"property":"og:url","content":"https://kingcxp.github.io/posts/C-Cpp-%E8%AF%AD%E8%A8%80%E4%B8%8E%E7%A8%8B%E5%BA%8F%E8%AE%BE%E8%AE%A1/71-cmake-sdl2.html"}],["meta",{"property":"og:site_name","content":"Kingcq's Blog"}],["meta",{"property":"og:title","content":"CMake 与 XMake：现代项目构建"}],["meta",{"property":"og:description","content":"引入：从 Makefile 到更现代的构建 上一篇的 Makefile 虽然能自动构建项目，但有几个明显的不足： 跨平台困难：Windows 用 MinGW 或 MSVC，Linux 用 GCC，macOS 用 Clang，Makefile 要为每个平台写不同版本。 依赖管理原始：如果项目依赖了第三方库（如 SDL2、OpenGL），找库、配置路径全靠..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-07-26T18:00:30.000Z"}],["meta",{"property":"article:author","content":"Kingcq"}],["meta",{"property":"article:tag","content":"链接库"}],["meta",{"property":"article:tag","content":"交叉编译"}],["meta",{"property":"article:tag","content":"构建工具"}],["meta",{"property":"article:tag","content":"SDL2"}],["meta",{"property":"article:tag","content":"XMake"}],["meta",{"property":"article:tag","content":"CMake"}],["meta",{"property":"article:published_time","content":"2026-07-20T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-07-26T18:00:30.000Z"}]]},"git":{"createdTime":1784108309000,"updatedTime":1785088830000,"contributors":[{"name":"Kingcq","username":"Kingcq","email":"404291187@qq.com","commits":4,"url":"https://github.com/Kingcq"}]},"readingTime":{"minutes":12.7,"words":3810},"filePathRelative":"posts/C-Cpp-语言与程序设计/71-cmake-sdl2.md","excerpt":"<h2>引入：从 Makefile 到更现代的构建</h2>\\n<p>上一篇的 <code>Makefile</code> 虽然能自动构建项目，但有几个明显的不足：</p>\\n<ul>\\n<li><span style=\\"color: #409EFF;\\">跨平台困难</span>：Windows 用 <code>MinGW</code> 或 <code>MSVC</code>，Linux 用 <code>GCC</code>，macOS 用 <code>Clang</code>，<code>Makefile</code> 要为每个平台写不同版本。</li>\\n<li><span style=\\"color: #409EFF;\\">依赖管理原始</span>：如果项目依赖了第三方库（如 <code>SDL2</code>、<code>OpenGL</code>），找库、配置路径全靠手动。</li>\\n<li><span style=\\"color: #409EFF;\\">语法简陋</span>：条件判断、循环、函数等高级功能写起来很别扭。</li>\\n</ul>","autoDesc":true}`);export{d as comp,r as data};
